package org.jsoup.nodes;

import org.jsoup.nodes.TextNode;
import org.junit.Test;
import org.jsoup.parser.Tag;
import static org.junit.Assert.*;

public class TextNodeTest {

    @Test
    public void textNodeConstructorTest() {
        TextNode node = new TextNode("example text");
        assertEquals("example text", node.text());
    }

    @Test
    public void nodeNameTest() {
        TextNode node = new TextNode("example text");
        assertEquals("#text", node.nodeName());
    }

    @Test
    public void textTest() {
        TextNode node = new TextNode("");
        node.text("example text");
        assertEquals("example text", node.text());
    }

    @Test
    public void getWholeTextTest() {
        TextNode node = new TextNode("example text");
        assertEquals("example text", node.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode node = new TextNode("");
        assertTrue(node.isBlank());

        node.text("example text");
        assertFalse(node.isBlank());
    }

    @Test
    public void splitTextTest() {
        TextNode node = new TextNode("splitme");
        TextNode splitNode = node.splitText(4);

        assertEquals("split", node.getWholeText());
        assertEquals("me", splitNode.getWholeText());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        TextNode node = new TextNode("example text");
        StringBuilder accum = new StringBuilder();
        node.outerHtmlHead(accum, 0, new Document("").outputSettings());

        assertEquals("example text", accum.toString());
    }

    @Test
    public void outerHtmlTailTest() {
        TextNode node = new TextNode("example text");
        StringBuilder accum = new StringBuilder();
        node.outerHtmlTail(accum, 0, new Document("").outputSettings());

        assertEquals("", accum.toString());
    }

    @Test
    public void toStringTest() {
        TextNode node = new TextNode("example text");
        assertEquals("TextNode{text='example text'}", node.toString());
    }

    @Test
    public void cloneTest() {
        TextNode node = new TextNode("example text");
        TextNode clone = node.clone();

        assertNotSame(node, clone);
        assertEquals(node.text(), clone.text());
    }

    @Test
    public void createFromEncodedTest() {
        TextNode node = TextNode.createFromEncoded("example encoded text", false);
        assertEquals("example encoded text", node.getWholeText());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String normalised = TextNode.normaliseWhitespace(" test text ");
        assertEquals("test text", normalised);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String normalised = TextNode.stripLeadingWhitespace(" test text ");
        assertEquals("test text ", normalised);
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        boolean isWhitespace = TextNode.lastCharIsWhitespace(new StringBuilder("test text "));
        assertTrue(isWhitespace);

        isWhitespace = TextNode.lastCharIsWhitespace(new StringBuilder("test text"));
        assertFalse(isWhitespace);
    }
}
